production.storyboard:
[
  {
    "panelNumber": 1,
    "originalText": "Lương tháng 10.000. Tôi làm mười năm, tăng thêm 2000. “Không cần đâu,” tôi nói, “tôi đã quyết định rồi.”",
    "description": "Composition: Medium shot. Lâm Vũ stands firmly near her desk. \nLighting: Bright morning office light. \nAction: Lâm Vũ (Female, 35, Outfit 1: White shirt, grey cardigan) raises a hand slightly in a gesture of refusal, looking directly at Tiểu Chu with a cold, determined expression. Tiểu Chu (Outfit 1: Pink dress) stands opposite her, looking surprised.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 2,
    "originalText": "Biểu cảm của Tiểu Chu có phần phức tạp. “Chị Lâm, chị thật sự đã nghĩ kỹ chưa? Bên ngoài không dễ tìm việc đâu.”",
    "description": "Composition: Close-up on Tiểu Chu's face. \nLighting: Bright office light. \nAction: Tiểu Chu (Female, 24, Outfit 1: Pink dress) knits her eyebrows in feigned concern, leaning forward slightly as if sharing a secret warning. Her expression mixes fake sympathy with manipulation.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 3,
    "originalText": "Tôi cười. “Cảm ơn sự quan tâm của cô.”",
    "description": "Composition: Close-up on Lâm Vũ's face. \nLighting: Bright office light. \nAction: Lâm Vũ (Outfit 1) smiles a polite but visibly sarcastic smile. Her eyes behind the glasses remain cold and distant.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 4,
    "originalText": "Tiểu Chu mấp máy môi như muốn nói gì đó, cuối cùng chỉ thở dài một tiếng rồi rời đi.",
    "description": "Composition: Medium shot, view from behind Lâm Vũ. \nLighting: Bright office light. \nAction: Tiểu Chu (Outfit 1) turns around and walks away, shoulders slightly slumped in defeat. Lâm Vũ (Outfit 1) stands still in the foreground, watching her go.",
    "timeOfDay": "Day (Next day)"
  },
  {
    "panelNumber": 5,
    "originalText": "Tối hôm đó, tôi nhận được lời mời phỏng vấn từ ba công ty. Đều là do headhunter giới thiệu. Trong đó có một công ty, đưa ra mức lương năm 600.000. Gấp hơn sáu lần thu nhập hiện tại của tôi.",
    "description": "Composition: Establishing shot of Lâm Vũ's bedroom. \nLighting: Dim night ambient lighting, blue glow from laptop screen. \nAction: Lâm Vũ (Outfit 2: Light blue pajamas) sits on her bed with a laptop on her lap. She is reading an email on the screen, her eyes widening slightly in pleasant surprise.",
    "timeOfDay": "Night"
  },
  {
    "panelNumber": 6,
    "originalText": "Tôi nhìn điện thoại, mỉm cười. 35 tuổi, ra ngoài thật sự không tìm được việc sao? Có lẽ vậy. Nhưng nếu bạn có mười năm tích lũy kỹ thuật... Giá trị của bạn là bao nhiêu, không phải công ty cũ quyết định.",
    "description": "Composition: Close-up on Lâm Vũ's face illuminated by the screen light. \nLighting: Soft screen glow highlighting her smile. \nAction: Lâm Vũ (Outfit 2) looks at her phone/laptop screen with a confident, contemplative smile. She takes off her glasses, looking relaxed and validated.",
    "timeOfDay": "Night"
  },
  {
    "panelNumber": 7,
    "originalText": "Tuần bàn giao đầu tiên, tôi bắt đầu viết tài liệu. Đúng vậy, cuối cùng tôi cũng bắt đầu viết tài liệu. Nhưng chỉ viết khung. Mã nguồn cốt lõi? Không viết. Mật khẩu cốt lõi? Không giao.",
    "description": "Composition: High-angle medium shot looking down at Lâm Vũ's desk. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3: Pale blue chiffon blouse, dark grey pencil skirt) sits at her desk typing on her computer. On the screen, a document titled 'Handover' is visible but contains very sparse text (bullet points only). She has a calculating, secretive look.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 8,
    "originalText": "Vương tổng tìm tôi. “Lâm Vũ, sao tài liệu chỉ có chút thế này?”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2: Dark blue business suit) stands by Lâm Vũ's desk, holding a very thin stack of papers, shaking them with an annoyed expression. Lâm Vũ (Outfit 3) sits calmly, turning her chair to face him.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 9,
    "originalText": "“Vương tổng, những hệ thống này là do tôi xây dựng suốt mười năm, nội dung quá nhiều, 30 ngày không viết xong được.”",
    "description": "Composition: Close-up on Lâm Vũ looking up. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) spreads her hands in a gesture of helplessness, her face calm and professional, explaining the situation reasonably.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 10,
    "originalText": "“Vậy cô tranh thủ lên.” “Vâng.” Tôi quay về tiếp tục “bàn giao”.",
    "description": "Composition: Over-the-shoulder shot from behind Lâm Vũ. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) walks away grumbling. Lâm Vũ (Outfit 3) turns back to her computer screen, her posture relaxed.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 11,
    "originalText": "Thật ra tôi chẳng bàn giao gì cả. Tôi đang đợi. Đợi họ nhận ra rằng, không có tôi, công ty này không vận hành nổi.",
    "description": "Composition: Extreme close-up on Lâm Vũ's eyes behind glasses. \nLighting: Reflection of code/screen in glasses. \nAction: Lâm Vũ (Outfit 3) stares at the screen with a sharp, calculating glint in her eyes. She is not typing, just waiting.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 12,
    "originalText": "Tiểu Chu bắt đầu hoảng. Cô ta cầm cái “tài liệu khung” tôi viết, hoàn toàn không hiểu. “Chị Lâm, hệ thống này đăng nhập thế nào?”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2: Cream blazer, black skirt) rushes to Lâm Vũ's desk, holding the thin document, looking panicked and confused. Lâm Vũ (Outfit 3) glances sideways at her.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 13,
    "originalText": "“Tài khoản và mật khẩu ở trong tài liệu.” “Em xem rồi, không có.”",
    "description": "Composition: Two-shot. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) points vaguely at the paper. Tiểu Chu (Outfit 2) frantically flips through the few pages, shaking her head.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 14,
    "originalText": "Tôi chỉ vào màn hình. “Cái này, admin, mật khẩu 1 2 3 4 5 6.”",
    "description": "Composition: Over-the-shoulder shot focusing on the screen. \nLighting: Screen light. \nAction: Lâm Vũ's hand (Outfit 3 sleeve) points to a login box on the screen. She looks bored as she dictates the simple password.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 15,
    "originalText": "Tiểu Chu thử đăng nhập. “Không vào được, báo sai mật khẩu.”",
    "description": "Composition: Close-up on the computer screen showing a red 'ERROR' message. \nLighting: Red glow from screen. \nAction: Tiểu Chu (Outfit 2) is visible in the reflection or leaning in, looking stressed as she types.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 16,
    "originalText": "Tôi liếc nhìn. Đó chỉ là giao diện đăng nhập bên ngoài. Phần backend cốt lõi, còn ba tầng xác thực.",
    "description": "Composition: Close-up on Lâm Vũ's face. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) watches with a slight smirk, thinking about the complex security layers she built.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 17,
    "originalText": "“Có thể là hệ thống vừa cập nhật,” tôi nói, “để tôi xem.” Tôi nhập mật khẩu thật, giao diện mở ra.",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) gently pushes Tiểu Chu (Outfit 2) aside, leans over the keyboard, and types a long, complex password quickly. The screen turns green/successful.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 18,
    "originalText": "Tiểu Chu thở phào nhẹ nhõm. “Chị Lâm, chị cho em mật khẩu được không?”",
    "description": "Composition: Medium shot of Tiểu Chu. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) sighs in relief, wiping sweat from her forehead, then looks at Lâm Vũ with a pleading expression.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 19,
    "originalText": "“Mật khẩu này không thể cho.” “Tại sao?”",
    "description": "Composition: Two-shot. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) leans back in her chair, crossing her arms and shaking her head firmly. Tiểu Chu (Outfit 2) looks shocked and confused.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 20,
    "originalText": "“Theo quy định công ty, mật khẩu hệ thống cốt lõi không được bàn giao bằng văn bản, phải bàn giao miệng, và phải có ba người chứng kiến.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) speaks with absolute seriousness and authority, raising three fingers to emphasize the 'three witnesses' rule.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 21,
    "originalText": "Tiểu Chu sững người. “Có quy định này sao? Sao em không biết?”",
    "description": "Composition: Close-up on Tiểu Chu. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) looks dumbfounded, blinking rapidly, feeling incompetent.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 22,
    "originalText": "“Quy định này do Vương tổng đặt ra từ mười năm trước,” tôi nói, “cô có thể hỏi ông ấy.”",
    "description": "Composition: Medium shot. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) gestures calmly towards the Manager's Office, passing the buck.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 23,
    "originalText": "Tiểu Chu đi hỏi Vương tổng. Vương tổng hoàn toàn không nhớ có quy định này. Bởi vì vốn dĩ không hề có.",
    "description": "Composition: Medium shot inside Manager's Office. \nLighting: Interior office light. \nAction: Tiểu Chu (Outfit 2) stands asking. Vương Tổng (Outfit 2) sits at his desk, scratching his head in confusion, looking vacant and unsure.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 24,
    "originalText": "Là tôi bịa ra. Nhưng Vương tổng cũng không còn cách nào khác. Vì tôi nói có, ông ta không dám nói không.",
    "description": "Composition: Split screen. Left: Lâm Vũ (Outfit 3) smiling slyly at her desk. Right: Vương Tổng (Outfit 2) nodding hesitantly to Tiểu Chu.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 25,
    "originalText": "“Vậy khi nào mới bàn giao?” Tiểu Chu hỏi tôi.",
    "description": "Composition: Medium shot at Lâm Vũ's desk. \nLighting: Bright office lighting. \nAction: Tiểu Chu (Outfit 2) returns to Lâm Vũ's desk, looking defeated and impatient.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 26,
    "originalText": "“Trước khi tôi rời đi, tôi sẽ sắp xếp.” “Vậy khi nào chị đi?” “30 ngày.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) smiles calmly, holding up a calendar or pointing to a date, emphasizing the full duration.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 27,
    "originalText": "Sắc mặt Tiểu Chu càng lúc càng khó coi. Cuối cùng cô ta cũng nhận ra, tấm bằng thạc sĩ 985 mà cô ta luôn tự hào, trước những hệ thống này, chẳng đáng một xu.",
    "description": "Composition: High angle shot looking down at a diminished Tiểu Chu. \nLighting: Office lighting casting a shadow over her. \nAction: Tiểu Chu (Outfit 2) stands looking down at the floor, fists clenched, face pale and humiliated.",
    "timeOfDay": "Day (One week later)"
  },
  {
    "panelNumber": 28,
    "originalText": "Tối hôm đó, tôi đi phỏng vấn. Là công ty trả lương năm 600.000 kia.",
    "description": "Composition: Wide shot of the Interview Room. \nLighting: Sophisticated night city view through glass walls, warm interior light. \nAction: Lâm Vũ (Outfit 4: Black business suit) sits confidently at a round table. The environment is modern and high-end.",
    "timeOfDay": "Evening"
  },
  {
    "panelNumber": 29,
    "originalText": "Người phỏng vấn hỏi tôi: “Cô Lâm, vì sao cô rời công ty trước?”",
    "description": "Composition: Over-the-shoulder shot from Lâm Vũ's perspective. \nLighting: Warm interior light. \nAction: The Interviewer (Male, 45, Outfit 1: Grey suit) sits opposite her, leaning forward with interest, clasping his hands.",
    "timeOfDay": "Evening"
  },
  {
    "panelNumber": 30,
    "originalText": "Tôi nghĩ một chút. “Vì tôi đáng giá 600.000.”",
    "description": "Composition: Close-up on Lâm Vũ's face. \nLighting: Flattering warm light. \nAction: Lâm Vũ (Outfit 4) looks straight at the interviewer, smiling confidently, radiating self-worth.",
    "timeOfDay": "Evening"
  },
  {
    "panelNumber": 31,
    "originalText": "Người phỏng vấn cười. “Tự tin. Tôi thích.”",
    "description": "Composition: Medium shot of Interviewer. \nLighting: Warm interior light. \nAction: The Interviewer (Outfit 1) laughs appreciatively, nodding his head in approval.",
    "timeOfDay": "Evening"
  },
  {
    "panelNumber": 32,
    "originalText": "Buổi phỏng vấn diễn ra rất suôn sẻ. Ba ngày sau, tôi nhận được offer.",
    "description": "Composition: Medium shot. \nLighting: Warm interior light. \nAction: Lâm Vũ (Outfit 4) and the Interviewer (Outfit 1) stand up and shake hands firmly across the table.",
    "timeOfDay": "Evening"
  },
  {
    "panelNumber": 33,
    "originalText": "Lương năm 600.000, chức danh Giám đốc kỹ thuật. Gấp hơn sáu lần thu nhập hiện tại của tôi.",
    "description": "Composition: Close-up of an Offer Letter document held in hands. \nLighting: Daytime indoor lighting (Home). \nAction: Lâm Vũ's hands (Outfit 2: Pajamas sleeve visible) hold the document. Focus on the text 'Salary: 600,000' and 'Position: Technical Director'.",
    "timeOfDay": "Day (3 days later)"
  },
  {
    "panelNumber": 34,
    "originalText": "Tôi nhìn offer, mỉm cười. Vương tổng nói đúng, 35 tuổi ra ngoài, đúng là không dễ tìm việc. Nhưng nếu có người chịu nhận bạn, thì mức họ trả chắc chắn cao hơn hiện tại.",
    "description": "Composition: Medium shot in Lâm Vũ's bedroom. \nLighting: Morning sunlight from window. \nAction: Lâm Vũ (Outfit 2) stands by the window holding the offer letter, looking out at the city with a peaceful, victorious smile.",
    "timeOfDay": "Day (3 days later)"
  },
  {
    "panelNumber": 35,
    "originalText": "Tuần thứ ba bàn giao công việc.",
    "description": "Composition: Establishing shot of the General Office Area with a calendar overlay or focus on a calendar on a desk showing a date 3 weeks later. \nLighting: Bright office lighting. \nAction: Busy office background. Time passing montage element.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 36,
    "originalText": "Tổng giám đốc Vương gọi tôi vào văn phòng. “Lâm Vũ, tài liệu của cô sao vẫn chưa viết xong?”",
    "description": "Composition: Medium shot in Manager's Office. \nLighting: Bright office lighting. \nAction: Vương Tổng (Outfit 2) stands behind his desk, slamming his hand on the thin handover document, looking furious. Lâm Vũ (Outfit 3: Blue blouse - re-wearing/rotated) stands calmly before him.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 37,
    "originalText": "“Tôi đang viết.” “Rốt cuộc cô có ý gì? Muốn dùng chuyện này để uy hiếp công ty à?”",
    "description": "Composition: Close-up on Vương Tổng. \nLighting: Harsh office lighting. \nAction: Vương Tổng (Outfit 2) points an accusing finger at Lâm Vũ, his face red with anger.",
    "timeOfDay": "Day (Week 3)"
  },
  {
    "panelNumber": 38,
    "originalText": "Tôi nhìn ông ta. “Vương tổng, tôi đang bàn giao đúng quy trình.”",
    "description": "Composition: Close-up on Lâm Vũ. \nLighting: Bright office lighting. \nAction: Lâm Vũ (Outfit 3) maintains a cool, unbothered expression, looking directly into the camera (at Vương Tổng), seemingly untouchable.",
    "timeOfDay": "Day (Week 3)"
  }
]

